// Recorded controller results on the district network: held-out SUMO evaluations (artifacts/ml/evaluation.json),
// generated by frontend/scripts/extract_controller_results.py. Numbers are copied, never recomputed.
import raw from '../data/controllerResults.json'

export type ControllerId = 'fixed_time' | 'queue_responsive' | 'safe_heuristic' | 'ml_forecast' | 'rl_ppo'
export type ControllerStatus = 'baseline' | 'default' | 'reference' | 'verified' | 'experimental' | 'unavailable'
export type MetricKey =
  | 'mean_wait_s'
  | 'mean_time_loss_s'
  | 'throughput_vph'
  | 'completed_fraction'
  | 'queue_mean_veh'
  | 'queue_max_veh'
  | 'pending_end'
  | 'teleports'
  | 'collisions'

export interface VsBaseline {
  diff: number
  ci95: [number, number]
  pct: number | null
  p: number | null
  better: number
  worse: number
  paired: number
}

export interface MetricStats {
  mean: number
  std: number
  min: number
  max: number
  vs?: VsBaseline
}

export interface ControllerSummary {
  n: number
  metrics: Partial<Record<MetricKey, MetricStats>>
}

export type SummaryGroup = Partial<Record<ControllerId, ControllerSummary>>

export interface EpisodeRow {
  c: ControllerId
  s: string
  seed: number
  wait: number
  loss: number
  queueMax: number
  teleports: number
}

export interface SummaryBlock {
  overall: SummaryGroup
  perScenario: Record<string, SummaryGroup>
}

export interface GateInfo {
  status: ControllerStatus
  failed: string[]
  checks: Record<string, boolean>
  pairs?: number | null
  meanWaitDiffS?: number | null
  meanWaitCi95?: [number, number] | null
  timeLossDiffS?: number | null
  timeLossCi95?: [number, number] | null
  teleportsDiff?: number | null
  throughputPct?: number | null
}

export interface ControllerInfo {
  title: string
  detail: string
  status: ControllerStatus
  gate?: GateInfo
}

export interface ResultsBlock {
  /** [first, last, count] */
  seeds: number[]
  episodes: number
  pairs: number
  vsFixed: SummaryBlock
  vsRules: SummaryBlock
  runs: EpisodeRow[]
}

export interface ControllerResults {
  schema: string
  source: { file: string; builtAt: string | null; split: string | null; seeds: number[]; note: string | null }
  network: { id: string; description: string }
  baseline: ControllerId
  flowstate: ControllerId
  controllers: Partial<Record<ControllerId, ControllerInfo>>
  safety: { minGreen: string; maxGreen: number; decision: number; note: string }
  scenarios: { id: string; title: string; description: string; heldOut: boolean }[]
  results: ResultsBlock
}

export const results = raw as unknown as ControllerResults

export interface MetricDef {
  key: MetricKey
  label: string
  unit: string
  better: 'lower' | 'higher'
  digits: number
  note: string
  /** displayed value = stored value * scale */
  scale?: number
}

export const METRICS: Record<MetricKey, MetricDef> = {
  mean_wait_s: { key: 'mean_wait_s', label: 'Mean wait', unit: 's', better: 'lower', digits: 1, note: 'Seconds each vehicle stood still (SUMO keeps a sliding 100 s window), over every vehicle that departed' },
  mean_time_loss_s: { key: 'mean_time_loss_s', label: 'Time lost per vehicle', unit: 's', better: 'lower', digits: 1, note: 'Seconds lost against free-flow speed, over every vehicle that departed; not capped' },
  throughput_vph: { key: 'throughput_vph', label: 'Throughput', unit: 'veh/h', better: 'higher', digits: 0, note: 'Vehicles that completed their trip, per hour' },
  completed_fraction: { key: 'completed_fraction', label: 'Trips completed', unit: '%', better: 'higher', digits: 1, note: 'Completed / departed by the end of the run', scale: 100 },
  queue_mean_veh: { key: 'queue_mean_veh', label: 'Mean queue', unit: 'veh', better: 'lower', digits: 1, note: 'Stopped vehicles, averaged over time' },
  queue_max_veh: { key: 'queue_max_veh', label: 'Peak queue', unit: 'veh', better: 'lower', digits: 0, note: 'Most stopped vehicles at once' },
  pending_end: { key: 'pending_end', label: 'Still on the road at the end', unit: 'veh', better: 'lower', digits: 1, note: 'Vehicles that had not finished their trip when the run ended' },
  teleports: { key: 'teleports', label: 'Gridlock teleports', unit: '', better: 'lower', digits: 2, note: 'Vehicles SUMO removed after being stuck; per run' },
  collisions: { key: 'collisions', label: 'Collisions', unit: '', better: 'lower', digits: 2, note: 'Distinct collision pairs; per run' },
}

export const scale = (m: MetricDef, v: number | null | undefined) => (v == null ? null : v * (m.scale ?? 1))

export type Verdict = 'better' | 'worse' | 'unclear'

export const MIN_PAIRED = 3

/** Clear only when the paired 95% interval of the difference excludes zero, over enough paired runs to have one. */
export function verdict(m: MetricDef, vs: VsBaseline | undefined): Verdict {
  if (!vs || vs.paired < MIN_PAIRED) return 'unclear'
  const [lo, hi] = vs.ci95
  if (lo <= 0 && hi >= 0) return 'unclear'
  const lower = hi < 0
  return (m.better === 'lower') === lower ? 'better' : 'worse'
}

export const VERDICT_LABEL: Record<Verdict, string> = { better: 'Clear improvement', worse: 'Clearly worse', unclear: 'No clear difference' }

/** Change expressed so that positive always means "the compared controller is better". */
export function improvementPct(m: MetricDef, base: number, vs: VsBaseline): { mid: number; lo: number; hi: number } | null {
  if (!base) return null
  const sign = m.better === 'lower' ? -1 : 1
  const a = (sign * vs.ci95[0] * 100) / base
  const b = (sign * vs.ci95[1] * 100) / base
  return { mid: (sign * vs.diff * 100) / base, lo: Math.min(a, b), hi: Math.max(a, b) }
}

/** Paired runs (same scenario + seed => identical vehicles) for two controllers. */
export function pairs(d: Pick<ResultsBlock, 'runs'>, a: ControllerId, b: ControllerId) {
  const key = (r: EpisodeRow) => `${r.s}/${r.seed}`
  const bs = new Map(d.runs.filter((r) => r.c === b).map((r) => [key(r), r]))
  return d.runs.filter((r) => r.c === a && bs.has(key(r))).map((r) => ({ s: r.s, seed: r.seed, a: r, b: bs.get(key(r))! }))
}

/** Experimental or unavailable controllers are shown, labelled, and never preselected. */
export const isExperimental = (status: ControllerStatus | undefined) => status === 'experimental' || status === 'unavailable'

/** Controllers present in the data, in display order. */
export const CONTROLLER_ORDER: ControllerId[] = ['fixed_time', 'queue_responsive', 'safe_heuristic', 'ml_forecast', 'rl_ppo']
export const presentControllers = (): ControllerId[] => CONTROLLER_ORDER.filter((c) => results.controllers[c])

export const GATE_CHECK_LABEL: Record<string, string> = {
  wait_ci_below_zero: 'mean wait is not clearly lower than the FlowState rules',
  time_loss_not_worse: 'time lost per vehicle is worse than the FlowState rules',
  no_teleport_regression: 'more gridlock teleports than the FlowState rules',
  no_throughput_regression: 'throughput is lower than the FlowState rules',
  no_scenario_regression: 'clearly worse than the FlowState rules in at least one scenario',
}
